ga9s(){return"\u041b\u0438\u0447\u043d\u0438\u044f\u0442 \u043a\u043b\u044e\u0447 \u0435 hex-\u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u044f\u043d\u0435 \u043d\u0430 \u0432\u0430\u0448\u0438\u044f nsec. \u0418 \u0434\u0432\u0430\u0442\u0430 \u0444\u043e\u0440\u043c\u0430\u0442\u0430 \u043e\u0441\u0438\u0433\u0443\u0440\u044f\u0432\u0430\u0442 \u043f\u044a\u043b\u0435\u043d \u0434\u043e\u0441\u0442\u044a\u043f \u0434\u043e \u0430\u043a\u0430\u0443\u043d\u0442\u0430."},
ga9g(){return"\u0412\u0430\u0448\u0438\u044f\u0442 \u043f\u0443\u0431\u043b\u0438\u0447\u0435\u043d \u043a\u043b\u044e\u0447 \u0443\u043d\u0438\u043a\u0430\u043b\u043d\u043e \u0438\u0434\u0435\u043d\u0442\u0438\u0444\u0438\u0446\u0438\u0440\u0430 \u0430\u043a\u0430\u0443\u043d\u0442\u0430 \u0432 Nostr \u043c\u0440\u0435\u0436\u0430\u0442\u0430. \u0411\u0435\u0437\u043e\u043f\u0430\u0441\u043d\u043e \u0435 \u0434\u0430 \u0433\u043e \u0441\u043f\u043e\u0434\u0435\u043b\u044f\u0442\u0435 \u2013 \u0432\u0441\u0435\u043a\u0438 \u043c\u043e\u0436\u0435 \u0434\u0430 \u0433\u043e \u0438\u0437\u043f\u043e\u043b\u0437\u0432\u0430, \u0437\u0430 \u0434\u0430 \u043d\u0430\u043c\u0435\u0440\u0438 \u0438 \u043f\u0440\u043e\u0432\u0435\u0440\u0438 \u0432\u0430\u0448\u0438\u0442\u0435 \u043f\u0443\u0431\u043b\u0438\u043a\u0430\u0446\u0438\u0438."},
